    "# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSES/reasoning-from-scratch.txt).",
    "# Source: https://github.com/rasbt/reasoning-from-scratch (reasoning_from_scratch/qwen3.py)",
